mapper.select:
select notice_id, notice_type, title, content, biz_id, receiver_id, is_read, read_time, create_time
from elevator_notice

    and receiver_id = #{receiverId}
    and is_read = #{isRead}
    and notice_type = #{noticeType}

order by notice_id desc

